 $taskLedger.sourceHashes=@{};foreach($source in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-envelope.mjs')){$taskLedger.sourceHashes[$source]=(Get-FileHash -LiteralPath (Join-Path $taskRoot ('live-management/'+$source))).Hash};Save-EnvelopeReceipt
 $public=Invoke-Command -Session $taskSession -ArgumentList $taskDirectory,$taskLedger.sourceHashes -ScriptBlock {param($directory,$hashes);$ErrorActionPreference='Stop';foreach($source in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1')){if((Get-FileHash -LiteralPath (Join-Path $directory $source)).Hash -cne $hashes[$source]){throw 'Transferred source differs'};. (Join-Path $directory $source)};@{key=(New-DnsRecoveryChannelKey (Join-Path $directory 'private'));clusterUid=[Guid]::NewGuid().ToString();accountUid=[Guid]::NewGuid().ToString()}|ConvertTo-Json -Depth 8}
