 $result=Invoke-Command -Session $taskSession -ArgumentList $taskDirectory -ScriptBlock {
  param($directory);$ErrorActionPreference='Stop';. (Join-Path $directory 'windows-dns-credential-recovery.ps1');. (Join-Path $directory 'windows-recovery-envelope.ps1');$private=Join-Path $directory 'private';$fixtures=Get-Content -LiteralPath ($directory+'\fixtures.json') -Raw|ConvertFrom-Json;$keyBefore=(Get-FileHash -LiteralPath ($private+'\recovery-channel-key.dpapi')).Hash;$pub=New-DnsRecoveryChannelKey $private;if($pub.kid -cne $fixtures.recipientId -or (Get-FileHash -LiteralPath ($private+'\recovery-channel-key.dpapi')).Hash -cne $keyBefore){throw 'Reloaded protected recipient key differs'};$checks=@()
